@extends('layouts.app') @section('title','Notifications') @section('page-title','Notifications') @section('content')<div class="toolbar"><p class="muted">Operational alerts and appointment updates.</p><form method="POST" action="{{ route('notifications.readAll') }}">@csrf @method('PATCH')<button class="btn btn-ghost">Mark all read</button></form></div><div class="panel notification-list">@forelse($notifications as $n)<div class="notification-item {{ $n->read_at?'':'unread' }}"><span class="notification-icon {{ $n->type }}">{{ $n->type==='warning'?'!':'✦' }}</span><div><b>{{ $n->title }}</b><p>{{ $n->message }}</p><small>{{ $n->created_at->diffForHumans() }}</small></div>@if(!$n->read_at)<form method="POST" action="{{ route('notifications.read',$n) }}">@csrf @method('PATCH')<button class="link">Mark read</button></form>@endif</div>@empty<div class="empty">No notifications.</div>@endforelse</div>{{ $notifications->links('partials.pagination') }}@endsection
